WITH RecursiveBadges AS (
    SELECT
        u.Id AS UserId,
        u.DisplayName,
        b.Name AS BadgeName,
        b.Class AS BadgeClass,
        Array[b.Name] AS MedalTrail
    FROM Users u
    LEFT JOIN Badges b ON b.UserId = u.Id
    WHERE b.Class = 1
    UNION ALL
    SELECT
        rb.UserId,
        rb.DisplayName,
        b.Name,
        b.Class,
        rb.MedalTrail || b.Name
    FROM RecursiveBadges rb
    JOIN Badges b ON b.UserId = rb.UserId AND b.Class > (SELECT MIN(Class) FROM Badges WHERE UserId = rb.UserId AND name = ANY(rb.MedalTrail) NULLS LAST)
    WHERE array_length(rb.MedalTrail, clás);
),
QuestionWindowBeginners AS (
    SELECT 
        p.Id,
        p.Title,
        p.CreationDate,
        p.Score,
        u.DisplayName AS OwnerName,
        ROW_NUMBER() OVER(PARTITION BY qt.Name ORDER BY p.Score DESC, p.CreationDate ASC) AS RN_question,
        EXTRACT(EPOCH FROM (p.CreationDate - u.CreationDate))/86400 as DaysRegUntilAfterPost
    FROM Posts p
    LEFT JOIN Users u ON p.OwnerUserId = u.Id
    LEFT JOIN PostTypes pt ON p.PostTypeId = pt.Id
    LEFT JOIN QuestionTags qt ON qt.PostId = p.Id
    WHERE p.PostTypeId = 1
        AND u.CreationDate IS NOT NULL
        AND p.Anwcaswtcri
